CREATE POLICY "lobby videos read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'lobby-videos');
CREATE POLICY "lobby videos upload own" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'lobby-videos' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "lobby videos delete own" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'lobby-videos' AND (storage.foldername(name))[1] = auth.uid()::text);